"use strict";self.window=self;let recipeCatalog=null;function loadRecipeCatalog(e){return recipeCatalog||(importScripts(e),recipeCatalog=self.RECIPES&&"object"==typeof self.RECIPES?self.RECIPES:{},recipeCatalog)}self.addEventListener("message",e=>{const t=e.data||{};if("load"===t.type&&t.id)try{const e=loadRecipeCatalog(t.src)[t.id]||null;if(!e)throw new Error("Fiche recette introuvable.");self.postMessage({type:"recipe",id:t.id,recipe:e})}catch(e){self.postMessage({type:"error",id:t.id,message:String(e?.message||e||"Chargement de la fiche impossible.")})}});